172: // 上下文参数：模型显式要了 -C/-A/-B 上下文（或 grep 结果里带上下文块），
173: // 说明是刻意取上下文，不应折叠成文件清单——折叠会把刚拿到的上下文又丢掉，逼出第二次 grep。
174: function wantsContext(args) {
175:   if (args === null || typeof args !== "object") return false;
176:   const keys = ["context", "-C", "after", "-A", "before", "-B", "contextLines", "around"];
177:   return keys.some((k) => args[k] !== undefined && args[k] !== null && args[k] !== 0 && args[k] !== false);
178: }
179: 
180: function capGrep(args, text) {
181:   const stats = grepStats(text);
182:   // 审计 B：折叠阈值改为**组合条件**（文件 ≥5 且 命中 ≥30）。单文件即使几十条也回行内容，
183:   // 避免「1 文件 24 条也被折叠成文件名」逼出一次多余 read（旧逻辑 files<=10||matches>20 即折）。
184:   if (wantsContext(args)) return null;
185:   if (stats.files < 5 || stats.matches < 30) return null;
186:   // 无文件信息（如 "Line 3: hit"）：只报总命中数，不回灌行内容。
187:   if (stats.files === 0) {
188:     return `[token-guard] grep 命中 ${stats.matches} 条（无文件信息），请缩范围或加 include。`;
189:   }
190:   // 有文件信息：折叠为「文件清单 + 每文件命中数与行号」，最多列 10 个文件。
191:   // 返回行号让模型能直接 read offset=<行号> 续读，不必二次 grep（审计 B）。
192:   const entries = [...stats.counts.entries()];
193:   const shown = entries.slice(0, 10).map(([file, k]) => {
194:     const nos = (stats.lineNos.get(file) ?? []).slice(0, 8);
195:     const tail = nos.length ? `  行 ${nos.join(",")}${k > nos.length ? ",…" : ""}` : "";
196:     return `${file}  (${k} 条${tail})`;
197:   });
198:   const lines = [
199:     `[token-guard] grep 命中 ${stats.matches} 条 / ${stats.files} 个文件，已折叠为文件清单 + 行号（不返回行内容）。按行号 read offset=<行号> 续读，或缩范围/加 include。`,
200:     ...shown,
201:   ];
202:   if (entries.length > 10) lines.push("...（其余文件已省略）");
203:   return lines.join("\n");
204: }
205: 
206: function capPwsh(command, text) {
207:   if (!BUILD_CMD.test(String(command || ""))) return null;
208:   const lines = text.split("\n");
209:   const errors = lines.filter((line) => ERROR_LINE.test(line));
210:   if (errors.length <= 20) return null;
211:   const omitted = lines.length - 15;
212:   return [
213:     PWSH_WARN,
214:     ...lines.slice(0, 10),
215:     `... (省略 ${omitted} 行错误) ...`,
216:     ...lines.slice(-5),
217:   ].join("\n");
218: }
219: 
220: function capOrchestrate(text) {
221:   if (text.length <= 1000 || !/无法读取|示意/.test(text)) return null;
222:   return `${text.slice(0, 1000)}\n(结果不可用，已截断。请宿主重新规划，不要沿用无法读取或示意性内容。)`;
223: }
224: 
225: /** 超限时返回截断文本；未超限返回 null。 */
226: function cappedText(exec, text) {
227:   const toolName = exec?.name;
228:   const args = exec?.arguments;
229:   if (toolName === "grep") return capGrep(args, text);
230:   if (toolName === "pwsh") return capPwsh(exec?.arguments?.command, text);
231:   if (toolName === "orchestrate") return capOrchestrate(text);
232:   if (toolName === "read") {
233:     const lines = text.split("\n");
234:     const hasRange = args != null && (args.offset != null || args.limit != null);
235:     // 审计 C2：.vue 单文件 340 行很常见，300 行门禁会逼出两次 read。按文件类型放宽：
236:     // .vue → 500，其余 → 300。仍按行数判，不改语义。
237:     const isVue = typeof args?.file_path === "string" && /\.vue$/i.test(args.file_path);
238:     const wholeGate = isVue ? 500 : 300;
239:     if (!hasRange && lines.length > wholeGate) {
240:       return `[token-guard] read 未带 offset/limit 且共 ${lines.length} 行（>${wholeGate}）。先 grep 定位，或带 offset/limit 分段读，不要整读。`;
241:     }
242:     if (hasRange && lines.length > 500) {
243:       return lines.slice(0, 500).join("\n")
244:         + "\n[token-guard] read 已超过 500 行，其余已截断。请缩小 offset/limit 范围后再读。";
245:     }
246:     return null;
247:   }
248:   if (toolName === "skill" && text.length > 2500) {
249:     return text.slice(0, 2500)
250:       + "\n[token-guard] skill 正文已截断。只保留前 2500 字，按已给出的步骤执行，不要为了补全文再整篇重读。";
251:   }
252:   return null;
253: }
254: 
255: export function apply(ctx, rawConfig) {
256:   const config = normalizeConfig(rawConfig);
257:   if (!config.enabled) return;
258:   const budget = config.inlineTokens;
259:   if (!Number.isSafeInteger(budget) || budget < 0) {
260:     throw new Error(`token-guard: inlineTokens must be a non-negative integer (got ${budget})`);
261:   }
262:   const threshold = config.readBudgetTokens;
263:   const watched = new Set(["read", ...config.extraTools]);
264: 
265:   ctx.on("tools/post-execute", async (exec, result, next) => {
266:     const decision = await next();
267:     if (decision.kind !== "accept" || Object.hasOwn(decision, "value")) return decision;
268:     let content = decision.content ?? result.content;
269:     if (!retainable(content) || content.length === 0) return decision;
270:     const shortened = cappedText(exec, fullTextOf(content));
271:     if (shortened) {
272:       content = [{ type: "text", text: shortened }];
273:       if (!watched.has(exec.name) || priceContent(content) <= threshold) {
274:         return { kind: "accept", content };
275:       }
276:     }
277:     if (!watched.has(exec.name)) return decision;
278:     if (priceContent(content) <= threshold) return decision;
279: 
280:     try {
281:       const owner = exec.agent?.session.header.id;
282:       if (owner === undefined) throw new Error(`no session owner for ${exec.name}`);
283:       const spillStore = ctx.get("spillStore");
284:       if (spillStore === undefined) throw new Error("no ctx.spillStore backend loaded");
285:       const ref = await spillStore.saveText({
286:         owner: { sessionId: owner },
287:         source: { kind: "tool", toolName: exec.name, callId: exec.callId, label: "result" },
288:         suggestedName: `${exec.name}.txt`,
289:         content: fullTextOf(content),
290:       });
291:       const retained = retainContent(content, budget);
292:       const notice = { type: "text", text: `\n\n${formatNotice(retained.omittedBytes, ref)}` };
293:       const rebuilt = retained.head.length + retained.tail.length === 0
294:         ? [notice]
295:         : mergeText([...retained.head, GAP, ...retained.tail, notice]);
296:       return { kind: "accept", content: rebuilt };
297:     } catch (error) {
298:       ctx.logger?.warn(`token-guard: ${String(error)}; keeping the inline content`);
299:       return decision;
300:     }
301:   }, { prepend: true });
302: }

(End of file - total 302 lines)
</content>"}]

