1: /**
2:  * dsh-cost-meter —— 会话内实时成本/未命中提醒（零依赖本地插件）。
3:  *
4:  * 与 dsh-mcp-gateway / dsh-agent-guard 同约束：装在 profile 之外，**不 import @deepseek-ai/***。
5:  *
6:  * 作用：把「60% 窗口收尾 / 每步未命中过高 / 累计等效成本过高」从口头规则变成**运行时自动提醒**。
7:  *   - 监听 `session/event`，从 assistant/message 的 usage 累加 uncached / cacheRead / output；
8:  *   - 每次 `agent/pre-step` 前检查阈值，越过就在本轮 messages 末尾追加一条 notice 提示模型收尾/换会话/别再整读；
9:  *   - 同一阈值只提醒一次（按会话记录），避免每步刷屏。
10:  *
11:  * 等效成本口径：cacheRead×0.1 + uncached + output×4。
12:  * 0.1 与 4 是假设倍率，待按实际计费校准，不是某次会话日志的证据。
13:  * 三键全 0 且没有 cacheReadTokens 的 usage 视为 absent：不进等效成本，只计 absentSteps。
14:  */
15: 
16: import { randomUUID } from "node:crypto";
17: 
18: export const name = "cost-meter";
19: export const inject = [];
20: 
21: /**
22:  * 配置归一化（零依赖，不 export Config 以免被 Cordis 当 schemastery schema 校验）。
23:  */
24: function normalizeConfig(input) {
25:   return {
26:     enabled: input?.enabled ?? true,
27:     sessionEquivBudget: input?.sessionEquivBudget ?? 8_000_000,
28:     // 单步未命中门槛 10k（2026-11-10 由 15k 下调，实测 >15k 时单步 reasoning 已失控）。
29:     perStepUncachedBudget: input?.perStepUncachedBudget ?? 10_000,
30:     // 单步 output 门槛 3k（2026-11-10 bug6369：step 46/49/50 单步 output ~10k，
31:     // 全耗在反复推翻自己的 reasoning 上——缺事实时不该脑内演算）。
32:     perStepOutputBudget: input?.perStepOutputBudget ?? 3_000,
33:     // 纯文本且无工具调用：3000 即疑似自我辩论（有工具的长输出仍走 3k）。
34:     // 审计 A.3：2k 在多文件正常推理里很常见，会误报；提到 3000 与 perStepOutput 对齐，
35:     // 只有真正开始空转（连续 2 步无工具且单步 >3k）才升级为硬指令。
36:     bareReasoningBudget: input?.bareReasoningBudget ?? 3_000,
37:     sessionUncachedBudget: input?.sessionUncachedBudget ?? 3_000_000,
38:     // 比 800 万更早的两档。15 万 ≈ 10 个单步未命中预算，或约两步 65k 级 cache 重读（按 0.1 倍率）。
39:     // 100 万比现有 800 万低一个数量级，避免累计档只在会话末期响一次。
40:     sessionEquivEarly: input?.sessionEquivEarly ?? 150_000,
41:     sessionEquivMid: input?.sessionEquivMid ?? 1_000_000,
42:   };
43: }
44: 
45: // 0.1 / 4：假设倍率，待计费校准。
46: const equivOf = (u) => (u.cacheRead || 0) * 0.1 + (u.uncached || 0) + (u.output || 0) * 4;
47: const fmt = (n) => n >= 1e6 ? (n / 1e6).toFixed(2) + 'M' : n >= 1e3 ? (n / 1e3).toFixed(0) + 'k' : String(Math.round(n));
48: 
49: /**
50:  * 从 assistant/message 的 data.usage 取数。
51:  * 三键全 0 且没有 cacheReadTokens：absent，不当成零成本。
52:  * 带 cacheReadTokens 的显式 0（四键）仍是真实记账。
53:  */
54: /** 能看到 content 才判定；看不到返回 unknown，避免误报。 */
55: export function classifyAssistant(event) {
56:   const d = event?.data ?? event ?? {};
57:   const content = d.content ?? d.message?.content;
58:   if (!Array.isArray(content)) return "unknown";
59:   const tool = content.some((b) => b && (b.type === "tool_use" || b.type === "toolCall" || b.type === "functionCall" || b.type === "tool_call"));
60:   return tool ? "tool" : "text";
61: }
62: 
63: function readUsage(event) {
64:   const d = event?.data ?? event;
65:   const u = d?.usage;
66:   if (!u) return undefined;
67:   const hasCacheRead = Object.prototype.hasOwnProperty.call(u, "cacheReadTokens")
68:     || Object.prototype.hasOwnProperty.call(u, "cacheRead");
69:   const absent = !hasCacheRead
70:     && u.uncachedInputTokens === undefined
71:     && u.inputTokens === 0
72:     && u.outputTokens === 0
73:     && (u.totalTokens === 0 || u.totalTokens === undefined);
74:   if (absent) return { absent: true };
75:   return {
76:     absent: false,
77:     uncached: u.uncachedInputTokens ?? u.inputTokens ?? 0,
78:     cacheRead: u.cacheReadTokens ?? u.cacheRead ?? 0,
79:     output: u.outputTokens ?? 0,
80:   };
81: }
82: 
83: let latestAcc;
84: 
85: /** 测试与排查：最近一次 enabled apply 的会话累计。 */
86: export function inspect(sessionId) {
87:   const a = latestAcc?.get(sessionId);
88:   if (!a) return undefined;
89:   return {
90:     uncached: a.uncached,
91:     cacheRead: a.cacheRead,
92:     output: a.output,
93:     lastOutput: a.lastOutput,
94:     steps: a.steps,
95:     absentSteps: a.absentSteps,
96:     equiv: equivOf(a),
97:     fired: [...a.fired],
98:   };
99: }
100: 
101: /** P3-11：从 pre-step 的 messages 里取 user 文本，判断是否同时含「修改+验证+提交」三要素。 */
102: function hasIntentSignal(messages) {
103:   if (!Array.isArray(messages)) return false;
104:   const text = messages
105:     .filter((m) => m && m.role === "user")
106:     .map((m) => {
107:       const c = m.content;
108:       if (typeof c === "string") return c;
109:       if (Array.isArray(c)) return c.map((b) => (typeof b === "string" ? b : b?.text ?? "")).join("\n");
110:       return "";
111:     })
112:     .join("\n");
