const capped = cappedText(exec, originalText, pwshCfg);
let content = originalContent;
// text===null：不裁剪，content 保持原样（绝不写成空串或 "null"）。
// 注意：不能在此直接 return——read 等 watched 工具即使「未裁剪」也仍需走「体积超阈值则落盘」旧路径。
if (capped.text !== null) {
  content = [{ type: "text", text: capped.text }];
}

// pwsh 读取类：spillRequested=true 时强制落盘（与裁剪后体积无关，杜绝全文丢失）。
if (capped.spillRequested === true) {
  try {
    const owner = exec.agent?.session.header.id;
    if (owner === undefined) throw new Error(`no session owner for ${exec.name}`);
    const spillStore = ctx.get("spillStore");
    if (spillStore === undefined) throw new Error("no ctx.spillStore backend loaded");
    // 落盘用「裁剪前原始全文」，保证可回读。
    const ref = await spillStore.saveText({
      owner: { sessionId: owner },
      source: { kind: "tool", toolName: exec.name, callId: exec.callId, label: "result" },
      suggestedName: `${exec.name}.txt`,
      content: originalText,
    });
    const notice = { type: "text", text: `\n\n${formatNotice(0, ref)}` };
    return { kind: "accept", content: [{ type: "text", text: capped.text + notice.text }] };
  } catch (error) {
    // 落盘失败：仍返回已裁剪有界文本（禁止回退完整原文）。
    ctx.logger?.warn(`token-guard: pwsh spill failed: ${String(error)}; returning bounded text`);
    return {
      kind: "accept",
      content: [{ type: "text", text: capped.text + "\n(落盘失败，全文未保存；请改用 read offset/limit 或缩小命令输出)" }],
    };
  }
}

// 其它工具（grep/read/skill/orchestrate）沿用旧逻辑：裁剪后体积仍超阈值且可落盘才走 spillStore。
if (!watched.has(exec.name) || priceContent(content) <= threshold) {
  return capped.text !== null ? { kind: "accept", content } : decision;
}
if (priceContent(content) <= threshold) return decision;

